<script setup lang="ts">
import { computed, ref, reactive, watch } from 'vue'
import { useRoute } from 'vue-router'
import { api, query } from '../../api/client'
import type { Page } from '../../api/types'
import StatusBadge from '../../components/StatusBadge.vue'
import RequestError from '../../components/RequestError.vue'
interface Log { id:string; username?:string; userId?:string; module?:string; action?:string; success:boolean; ip:string; createdAt:string; userAgent?:string; reason?:string; requestId?:string; targetType?:string; targetId?:string; requestSummary?:unknown; beforeData?:unknown; afterData?:unknown; durationMs?:number }
const route=useRoute(),login=computed(()=>route.path==='/admin/login-logs'),rows=ref<Log[]>([]),total=ref(0),page=ref(1),loading=ref(false),error=ref<Error|null>(null),drawer=ref(false),selected=ref<Log>(),dates=ref<[string,string]|null>(null)
const filters=reactive({username:'',module:'',action:'',success:'',ip:''})
let request=0
async function load(){const current=++request;loading.value=true;error.value=null;rows.value=[];try{const result=await api<Page<Log>>(`${login.value?'/admin/login-logs':'/admin/audit-logs'}?${query({page:page.value,pageSize:20,username:filters.username,success:filters.success,dateFrom:dates.value?.[0],dateTo:dates.value?.[1],...(login.value?{ip:filters.ip}:{module:filters.module,action:filters.action})})}`);if(current===request){rows.value=result.items;total.value=result.total}}catch(e){if(current===request)error.value=e as Error}finally{if(current===request)loading.value=false}}
function reset(){Object.assign(filters,{username:'',module:'',action:'',success:'',ip:''});dates.value=null;page.value=1;void load()}
watch(()=>route.path,reset,{immediate:true})
</script>
<template><div class="page-head"><div><h1>{{ login?'登录日志':'审计日志' }}</h1><p>{{ login?'检索账号登录结果、来源与失败原因':'追踪系统关键操作、变更记录与执行结果' }}</p></div><span class="muted small">只读日志</span></div><form class="surface filter-bar" @submit.prevent="page=1;load()"><label class="filter-field">用户<el-input v-model="filters.username" placeholder="账号 / 用户" clearable/></label><label class="filter-field">时间范围<el-date-picker v-model="dates" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ssZ" start-placeholder="开始时间" end-placeholder="结束时间" style="width:340px"/></label><label class="filter-field">结果<el-select v-model="filters.success" placeholder="全部结果" clearable><el-option label="成功" value="true"/><el-option label="失败" value="false"/></el-select></label><template v-if="!login"><label class="filter-field">模块<el-input v-model="filters.module" placeholder="模块代码" clearable/></label><label class="filter-field">动作<el-input v-model="filters.action" placeholder="如 USER_CREATE" clearable/></label></template><label v-else class="filter-field">IP 地址<el-input v-model="filters.ip" placeholder="来源 IP" clearable/></label><div class="actions"><el-button type="primary" native-type="submit">查询</el-button><el-button @click="reset">重置</el-button></div></form><RequestError :error="error" @retry="load"/><section class="surface table-panel"><div class="panel-head"><h2>{{ login?'登录记录':'操作记录' }}</h2><small class="muted">共 {{ total }} 条</small></div><el-table v-loading="loading" :data="rows" empty-text="此筛选条件下暂无日志"><el-table-column prop="createdAt" label="时间" min-width="190"/><el-table-column label="用户" min-width="130"><template #default="{row}">{{ row.username??row.userId??'—' }}</template></el-table-column><template v-if="!login"><el-table-column prop="module" label="模块" min-width="120"/><el-table-column prop="action" label="动作" min-width="180"/><el-table-column prop="targetId" label="目标对象" min-width="140" show-overflow-tooltip/></template><el-table-column label="结果" width="85"><template #default="{row}"><StatusBadge :status="row.success"/></template></el-table-column><el-table-column prop="ip" label="IP 地址" min-width="130"/><template v-if="login"><el-table-column prop="reason" label="失败原因" min-width="200" show-overflow-tooltip/><el-table-column prop="userAgent" label="User-Agent" min-width="200" show-overflow-tooltip/></template><el-table-column v-else prop="durationMs" label="耗时 (ms)" align="right" width="100"/><el-table-column label="操作" width="80" fixed="right"><template #default="{row}"><el-button text type="primary" size="small" @click="selected=row;drawer=true">详情</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total, prev, pager, next" @current-change="load"/></div></section><el-drawer v-model="drawer" :title="login?'登录记录详情':'审计记录详情'" size="min(680px,100vw)"><div v-if="selected" class="details"><el-descriptions :column="1" border><el-descriptions-item label="时间">{{ selected.createdAt }}</el-descriptions-item><el-descriptions-item label="用户">{{ selected.username??selected.userId }}</el-descriptions-item><el-descriptions-item label="结果"><StatusBadge :status="selected.success"/></el-descriptions-item><el-descriptions-item label="IP">{{ selected.ip }}</el-descriptions-item><template v-if="login"><el-descriptions-item label="User-Agent">{{ selected.userAgent??'—' }}</el-descriptions-item><el-descriptions-item label="失败原因">{{ selected.reason??'—' }}</el-descriptions-item></template><template v-else><el-descriptions-item label="请求编号">{{ selected.requestId }}</el-descriptions-item><el-descriptions-item label="模块 / 动作">{{ selected.module }} / {{ selected.action }}</el-descriptions-item><el-descriptions-item label="目标对象">{{ selected.targetType }} / {{ selected.targetId }}</el-descriptions-item><el-descriptions-item label="耗时">{{ selected.durationMs??'—' }} ms</el-descriptions-item></template></el-descriptions><template v-if="!login"><div v-for="part in [{label:'脱敏请求摘要',value:selected.requestSummary},{label:'变更前',value:selected.beforeData},{label:'变更后',value:selected.afterData}]" :key="part.label"><h2>{{ part.label }}</h2><pre>{{ part.value ? JSON.stringify(part.value,null,2) : '无记录' }}</pre></div></template></div></el-drawer></template>
